INSERT INTO `shop_goods_description` (`id`, `created_at`, `updated_at`, `deleted_at`, `goods_id`, `notice`, `details`) VALUES (520, '2023-11-23 18:28:23.317', '2023-11-23 18:31:18.323', NULL, 554, '', '<p>产品特点：中国首款会呼吸的春卷， 背后两大核心优势，一者独树一帜的春卷皮，自然中透着气，易吸热及</p><p>滤油，保持产品内外的一致香脆而不油腻。二者春卷馅全部来全国纬度不同十几个自有农场的全产链蔬菜基</p><p>地，保证新鲜、营养健康和安全。</p><p>产品口号：孚美春卷 新鲜会呼吸</p><p>产品规格： 15g/根（40克g/根）， 12条/包， 24包/箱， 4.32kg/箱（11.52kg/箱）</p><p>食用场景： 逛街旅游、 早餐、宴席</p>');
INSERT INTO `shop_goods_description` (`id`, `created_at`, `updated_at`, `deleted_at`, `goods_id`, `notice`, `details`) VALUES (521, '2023-11-23 18:29:42.172', '2023-11-23 18:29:42.172', NULL, 555, '', '<p>产品特点：中国首款会呼吸的春卷， 背后两大核心优势，一者独树一帜的春卷皮，自然中透着气，易吸热及</p><p>滤油，保持产品内外的一致香脆而不油腻。二者春卷馅全部来全国纬度不同十几个自有农场的全产链蔬菜基</p><p>地，保证新鲜、营养健康和安全。</p><p>产品口号：蔬菜三角饼 新鲜会呼吸</p><p>产品规格： 15g/粒， 16粒/包， 24包/箱， 5.76kg/箱</p><p>食用场景： 逛街旅游、 早餐、宴席</p>');
