  `deleted_at` datetime(3) DEFAULT NULL,
  `name` varchar(255) NOT NULL COMMENT '商品名称',
  `category_id` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT '分类id',
  `brand_id` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT '品牌Id',
  `goods_area` tinyint(1) NOT NULL DEFAULT 0 COMMENT '所属区域(0普通商品 1积分商城 )',
  `spec_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '规格类型(0单规格 1多规格)',
  `unit` varchar(20) NOT NULL DEFAULT '件' COMMENT '商品单位(盒、件、瓶、克等)',
  `origin` varchar(255) NOT NULL DEFAULT '' COMMENT '产地',
  `cost_price` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '成本价(原价|积分)',
