  `is_first` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否首页(0否 1是)',
  `is_hot` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否热销(0否 1是)',
  `is_new` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否上新(0否 1是)',
  `pay_count` int(10) DEFAULT NULL COMMENT '冗余字段',
