-- ----------------------------
-- Table structure for shop_order
-- ----------------------------
DROP TABLE IF EXISTS `shop_order`;
CREATE TABLE `shop_order` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户id',
  `order_sn` varchar(50) NOT NULL COMMENT '订单编号',
  `goods_area` tinyint(1) DEFAULT NULL COMMENT '所属区域(0普通 1积分商城)',
  `shipment_name` varchar(20) NOT NULL COMMENT '收货人姓名',
  `shipment_mobile` varchar(11) NOT NULL COMMENT '收货人手机号',
  `shipment_address` varchar(255) NOT NULL COMMENT '收货人地址',
  `shipment_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '收货方式 0配送 1自提',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '商品总数量',
  `total` decimal(14,2) NOT NULL COMMENT '订单商品总金额',
  `finish` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '实付金额',
  `postage` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '邮费',
  `pick_up_number` int(11) DEFAULT NULL COMMENT '取餐号',
  `settlement_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '结算类型(0现结 1月结未结账 2月结已结账)',
  `status` tinyint(2) NOT NULL DEFAULT 0 COMMENT '订单状态(0未付款 1已付款待发货 2 已发货 3已收货)',
  `payment` tinyint(1) NOT NULL DEFAULT 0 COMMENT '支付方式(1余额 2微信 3支付宝 4积分 5线下支付)',
  `payment_info` varchar(255) DEFAULT NULL COMMENT '支付详情信息',
  `payment_openid` varchar(255) DEFAULT NULL COMMENT '支付openId',
  `transation_id` varchar(255) DEFAULT NULL COMMENT '支付流水订单号',
  `gift_points` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '赠送积分数量',
  `remarks` varchar(255) DEFAULT NULL COMMENT '留言',
  `status_cancel` tinyint(1) NOT NULL DEFAULT 0 COMMENT '取消状态(0未取消 1用户取消 2后台取消 3超时取消)',
  `status_refund` tinyint(1) NOT NULL COMMENT '退款状态(0未退款 1退款中 2已退款 3退款失败)',
  `pay_time` datetime(3) DEFAULT NULL COMMENT '支付时间',
  `shipment_time` datetime(3) DEFAULT NULL COMMENT '发货时间',
  `receive_time` datetime(3) DEFAULT NULL COMMENT '收货时间',
  `cancel_time` datetime(3) DEFAULT NULL COMMENT '取消时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=223 DEFAULT CHARSET=utf8mb4  ROW_FORMAT=DYNAMIC COMMENT='订单表';

