  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户id',
  `order_id` bigint(20) unsigned NOT NULL COMMENT '订单Id',
  `reason` varchar(255) DEFAULT NULL COMMENT '申请原因',
  `amount` decimal(14,2) NOT NULL COMMENT '退款金额',
  `status` tinyint(1) NOT NULL COMMENT '售后状态(-1 拒绝售后 0未处理 1已退款)',
  `refund_status` tinyint(1) NOT NULL COMMENT '退款状态(0未处理 1退款中 2退款成功)',
  `reply` varchar(255) DEFAULT NULL COMMENT '售后说明',
  `process_time` datetime DEFAULT NULL COMMENT '售后处理时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4  ROW_FORMAT=DYNAMIC COMMENT='订单售后表';

-- ----------------------------
-- Records of shop_order_return
-- ----------------------------
