-- ----------------------------
-- Table structure for sys_users
-- ----------------------------
DROP TABLE IF EXISTS `sys_users`;
CREATE TABLE `sys_users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `uuid` varchar(191) DEFAULT NULL COMMENT '用户UUID',
  `username` varchar(191) DEFAULT NULL COMMENT '用户登录名',
  `password` varchar(191) DEFAULT NULL COMMENT '用户登录密码',
  `safe_password` varchar(191) DEFAULT NULL COMMENT '用户安全密码',
  `nick_name` varchar(191) DEFAULT '系统用户' COMMENT '用户昵称',
  `side_mode` varchar(191) DEFAULT 'dark' COMMENT '用户侧边主题',
  `header_img` varchar(191) DEFAULT 'https://qmplusimg.henrongyi.top/gva_header.jpg' COMMENT '用户头像',
  `base_color` varchar(191) DEFAULT '#fff' COMMENT '基础颜色',
  `active_color` varchar(191) DEFAULT '#1890ff' COMMENT '活跃颜色',
  `authority_id` bigint(20) unsigned DEFAULT 888 COMMENT '用户角色ID',
  `phone` varchar(191) DEFAULT NULL COMMENT '用户手机号',
  `email` varchar(191) DEFAULT NULL COMMENT '用户邮箱',
  `enable` bigint(20) DEFAULT 1 COMMENT '用户是否被冻结 1正常 2冻结',
  `open_id` varchar(191) DEFAULT NULL COMMENT 'OpenId',
  `invitation_code` varchar(191) DEFAULT NULL COMMENT '推荐码',
  `login_ip` varchar(191) DEFAULT NULL COMMENT '登录IP',
  `login_time` datetime(3) DEFAULT NULL COMMENT '最后登录时间',
  `sex` bigint(20) DEFAULT 0 COMMENT '性别',
  `origin_contact_name` varchar(50) DEFAULT NULL COMMENT '联系人姓名',
  `change_contact_name` varchar(255) DEFAULT NULL COMMENT '联系人姓名修改待审核',
  `origin_customer_name` varchar(255) DEFAULT NULL COMMENT '客户名称、公司名称',
  `change_customer_name` varchar(255) DEFAULT NULL COMMENT '客户名称、公司名称待审核',
  `audit_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT ' 审核状态 0新注册未填写信息 1已通过 2已填写未审核 3修改信息待审核 4审核不通过',
  `audit_remark` varchar(255) DEFAULT NULL COMMENT '审核备注',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_sys_users_deleted_at` (`deleted_at`) USING BTREE,
  KEY `idx_sys_users_uuid` (`uuid`) USING BTREE,
  KEY `idx_sys_users_username` (`username`) USING BTREE,
  KEY `idx_sys_users_open_id` (`open_id`) USING BTREE,
  KEY `idx_sys_users_invitation_code` (`invitation_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4  ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of sys_users
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for user_account
-- ----------------------------
DROP TABLE IF EXISTS `user_account`;
CREATE TABLE `user_account` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户id',
  `group_id` bigint(20) unsigned NOT NULL COMMENT '币种id',
  `amount` float NOT NULL DEFAULT 0 COMMENT '可用余额',
  `freeze_amount` float NOT NULL DEFAULT 0 COMMENT '冻结余额',
  `lock_amount` float NOT NULL DEFAULT 0 COMMENT '锁仓金额',
  `in_amount` float NOT NULL DEFAULT 0 COMMENT '累计入账数额',
  `out_amount` float NOT NULL DEFAULT 0 COMMENT '累计出账数额',
  `status` bigint(20) DEFAULT 1 COMMENT '账户状态（0禁用 1启用）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uid_coin` (`user_id`,`group_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `group_id` (`group_id`) USING BTREE,
  KEY `idx_user_account_deleted_at` (`deleted_at`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=165 DEFAULT CHARSET=utf8mb4  ROW_FORMAT=DYNAMIC COMMENT='用户账户表';

