-- Records of user_account
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for user_account_group
-- ----------------------------
DROP TABLE IF EXISTS `user_account_group`;
CREATE TABLE `user_account_group` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `name_en` varchar(20) NOT NULL COMMENT '币中英文名',
  `name_cn` varchar(20) NOT NULL COMMENT '币种中文名',
  `places` tinyint(1) NOT NULL DEFAULT 4 COMMENT '小数点位数',
  `status` bigint(20) NOT NULL DEFAULT 1 COMMENT '状态(0禁用 1启用)',
  `sync` tinyint(1) NOT NULL DEFAULT 0 COMMENT '同步状态(-1 同步失败 0未同步 1同步中 2已同步) 生成用户对应的币种账户和币种流水表',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `name_en` (`name_en`) USING BTREE,
  KEY `idx_user_account_group_deleted_at` (`deleted_at`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4  ROW_FORMAT=DYNAMIC COMMENT='账户分类（币种）表';

