-- Records of user_account_group
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for user_address
-- ----------------------------
DROP TABLE IF EXISTS `user_address`;
CREATE TABLE `user_address` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL DEFAULT 0 COMMENT '用户id',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认',
  `name` varchar(20) NOT NULL COMMENT '收货人姓名',
  `mobile` varchar(11) NOT NULL COMMENT '手机号',
  `area` varchar(20) NOT NULL DEFAULT '' COMMENT '收货人地区编码',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标志点位置',
  `address` varchar(255) NOT NULL COMMENT '地址',
  `detail` varchar(255) NOT NULL DEFAULT '' COMMENT '详细地址',
  `lable` varchar(20) NOT NULL DEFAULT '' COMMENT '标签',
  `sex` tinyint(1) NOT NULL DEFAULT 1 COMMENT '性别 1先生 2女士',
  `longitude` decimal(10,6) NOT NULL DEFAULT 0.000000 COMMENT '经度',
  `latitude` decimal(10,6) NOT NULL DEFAULT 0.000000 COMMENT '纬度',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4  ROW_FORMAT=DYNAMIC COMMENT='用户收货地址表';

