-- ----------------------------
-- Table structure for user_relation
-- ----------------------------
DROP TABLE IF EXISTS `user_relation`;
CREATE TABLE `user_relation` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `user_id` bigint(20) unsigned NOT NULL COMMENT '用户id',
  `username` varchar(191) NOT NULL COMMENT '用户名',
  `referral_id` bigint(20) unsigned NOT NULL COMMENT '推荐人ID',
  `referral_name` varchar(191) NOT NULL COMMENT '推荐人用户名',
  `dai` int(11) NOT NULL DEFAULT 1 COMMENT '代数',
  `path` text NOT NULL COMMENT '推荐路径(例: ,1,2,3,)',
  `num` int(11) NOT NULL DEFAULT 0 COMMENT '推荐关系直推累计人数',
  `team_num` int(11) NOT NULL DEFAULT 0 COMMENT '推荐关系团队累计人数',
  `active_num` int(11) NOT NULL DEFAULT 0 COMMENT '推荐关系直推有效累计人数',
  `team_active_num` int(11) NOT NULL DEFAULT 0 COMMENT '推荐关系团队有效累计人数',
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '推荐关系自身消费金额（仅普通商品）',
  `referral_amount` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '推荐关系直推消费金额',
  `referral_team_amount` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '推荐关系团队消费金额',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `user_id` (`user_id`) USING BTREE,
  UNIQUE KEY `username` (`username`) USING BTREE,
  KEY `referral_id` (`referral_id`) USING BTREE,
  KEY `referral_name` (`referral_name`) USING BTREE,
  FULLTEXT KEY `path` (`path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4  ROW_FORMAT=DYNAMIC COMMENT='用户推荐关系表';

-- ----------------------------
-- Records of user_relation
-- ----------------------------
BEGIN;
COMMIT;

